import re
from typing import Dict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parses an INI string according to the specified rules."""

    result: Dict[str, Dict[str, str]] = {}
    default_section: Dict[str, str] = {}
    current_section: str = None
    current_key: str = None
    current_value: str = None
    in_string: bool = False
    interpolation_stack: list[tuple[str, str]] = []

    for line in text.splitlines():
        line = line.strip()

        if not line or line.startswith((';', '#')):
            continue

        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if current_section is not None:
                if current_key:
                    if current_value is None:
                        current_value = ''
                    result[current_section][current_key] = current_value

            current_section = section_name
            result[current_section] = {}
            current_key = None
            current_value = None
            in_string = False
            interpolation_stack = []
        else:
            if current_section is None:
                raise ValueError("Key line before section header")

            match = re.match(r'(\w+)\s*[:=]\s*(.+)', line)
            if not match:
                raise ValueError("Malformed line")

            key, value = match.groups()
            key = key.lower().strip()

            if current_key is None:
                current_key = key

                in_string = False

                # Extract value, handling quotes and comments
                value_start = 0
                while value_start < len(value):
                    if value[value_start] == '"':
                        value_start += 1
                        value_end = value.find('"', value_start)
                        if value_end == -1:
                            current_value = value[value_start-1:]
                            break
                        current_value = value[value_start : value_end]
                        value_start = value_end + 1
                    else:
                        comment_start = value.find(';', value_start)
                        hash_comment_start = value.find('#', value_start)

                        if comment_start != -1 and (hash_comment_start == -1 or comment_start < hash_comment_start):
                            current_value = value[value_start:comment_start].strip()
                            break
                        elif hash_comment_start != -1:
                            current_value = value[value_start:hash_comment_start].strip()
                            break
                        else:
                            current_value = value[value_start:].strip()
                            break

            else:
                # Continuation line
                current_value += "\n" + value

    if current_section is not None and current_key is not None:
        if current_value is None:
            current_value = ''
        result[current_section][current_key] = current_value


    #Apply DEFAULT section
    for key, value in default_section.items():
        if key not in result.get('DEFAULT', {}):
            result['DEFAULT'] = result.get('DEFAULT',{})
            result['DEFAULT'][key] = value

    final_result: Dict[str, Dict[str, str]] = {}
    for section_name, section_data in result.items():
        if section_name != 'DEFAULT':
            #Inherit from default
            inherited_data = default_section.copy()
            for key, value in section_data.items():
                inherited_data[key] = value
            final_result[section_name] = inherited_data
        else:
            final_result[section_name] = section_data


    for section_name, section_data in final_result.items():
        for key, value in section_data.items():
            final_result[section_name][key] = interpolate(value, final_result)

    return final_result



def interpolate(value: str, data: Dict[str, Dict[str, str]]) -> str:
    """Interpolates values in a string using the provided data."""

    def replace_match(match):
        full_match = match.group(0)
        if full_match.startswith("${"):
            ref = full_match[2:-1]
            if ":" in ref:
                section, key = ref.split(":", 1)
                if section in data and key in data[section]:
                    return data[section][key]
                else:
                    raise KeyError(f"Section or key not found: {section}:{key}")
            else:
                if "DEFAULT" in data and ref in data["DEFAULT"]:
                    return data["DEFAULT"][ref]
                else:
                    raise KeyError(f"Key not found: {ref}")
        else:
            return match.group(0)

    pattern = r"\${[^}]+}"

    while True:
        original_value = value
        value = re.sub(pattern, replace_match, value)
        if value == original_value:
            break

    return value
