from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self.clock()
        expired = []

        # Remove expired entries
        for k, (v, expiry) in self.cache.items():
            if now >= expiry:
                expired.append(k)

        for k in expired:
            del self.cache[k]
            self.expirations += 1

        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = (value, now + self.ttl)
            return

        if len(self.cache) >= self.capacity:
            lru_key, _ = self.cache.popitem(last=False)
            self.evictions += 1

        self.cache[key] = (value, now + self.ttl)
        self.cache.move_to_end(key)

    def get(self, key, default=None):
        if self.capacity == 0:
            self.misses += 1
            return default

        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if now >= expiry:
                del self.cache[key]
                self.expirations += 1
                self.misses += 1
                return default
            else:
                self.hits += 1
                self.cache.move_to_end(key)
                self.cache[key] = (value, expiry)
                return value
        else:
            self.misses += 1
            return default

    def __len__(self):
        now = self.clock()
        count = 0
        for _, (value, expiry) in self.cache.items():
            if now < expiry:
                count += 1
        return count

    def stats(self):
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations,
        }
