import re

def parse_duration(s: str) -> int:
    """Converts a duration string into a total number of seconds.

    Supported units: `h` (hours), `m` (minutes), `s` (seconds). Units are case-insensitive.
    Each part is a non-negative integer followed by a unit, e.g. "1h30m", "45s", "2H", "1h 5m 10s", "90m".
    Whitespace is allowed before, after and between parts.
    Units must appear in the order h, m, s and each at most once.
    Raise ValueError for empty/blank strings, numbers without a unit, unknown units, decimals, repeated units, or units out of order.
    """

    s = s.strip()
    if not s:
        raise ValueError("Empty duration string")

    parts = re.findall(r"(\d+)[hms]", s, re.IGNORECASE)
    units = re.findall(r"[hms]", s, re.IGNORECASE)

    if not parts:
        raise ValueError("Invalid duration format")

    if len(parts) != len(units):
        raise ValueError("Invalid duration format: numbers without unit")

    hours = 0
    minutes = 0
    seconds = 0

    hour_found = False
    minute_found = False
    second_found = False

    for i in range(len(parts)):
        try:
            value = int(parts[i])
        except ValueError:
            raise ValueError("Invalid duration format: non-integer value")

        unit = units[i].lower()

        if unit == 'h':
            if hour_found:
                raise ValueError("Repeated unit: hour")
            hours = value
            hour_found = True
        elif unit == 'm':
            if hour_found and not minute_found:
                pass
            elif not hour_found and minute_found:
                raise ValueError("Units out of order")
            if minute_found:
                raise ValueError("Repeated unit: minute")
            minutes = value
            minute_found = True
        elif unit == 's':
            if hour_found and minute_found and not second_found:
                pass
            elif hour_found and not minute_found and second_found:
                raise ValueError("Units out of order")
            elif not hour_found and minute_found and second_found:
                raise ValueError("Units out of order")
            if second_found:
                raise ValueError("Repeated unit: second")
            seconds = value
            second_found = True
        else:
            raise ValueError("Unknown unit")

    total_seconds = hours * 3600 + minutes * 60 + seconds

    return total_seconds
