def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(list(set(nums)))
    result = []
    start = nums[0]
    end = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == end + 1:
            end = nums[i]
        else:
            if start == end:
                result.append(str(start))
            else:
                result.append(f"{start}..{end}")
            start = nums[i]
            end = nums[i]

    if start == end:
        result.append(str(start))
    else:
        result.append(f"{start}..{end}")

    return ",".join(result)
